import itertools

edges = []
for i in range(7):
    for j in range(7, 14):
        edges.extend([i, j])

def is_triangle_free(edges, n):
    adj = {i: set() for i in range(n)}
    for i in range(0, len(edges), 2):
        u, v = edges[i], edges[i+1]
        adj[u].add(v)
        adj[v].add(u)

    for i in range(n):
        for j in adj[i]:
            if j > i:
                if len(adj[i].intersection(adj[j])) > 0:
                    return False
    return True

def is_maximal(edges, n):
    adj = {i: set() for i in range(n)}
    for i in range(0, len(edges), 2):
        u, v = edges[i], edges[i+1]
        adj[u].add(v)
        adj[v].add(u)

    for i in range(n):
        for j in range(i+1, n):
            if j not in adj[i]:
                if len(adj[i].intersection(adj[j])) == 0:
                    return False
    return True

print("Triangle free:", is_triangle_free(edges, 14))
print("Maximal:", is_maximal(edges, 14))
